// Phân tích độ phức tạp Time & Space trên các thuật toán tìm kiếm mảng
// 1. Tìm kiếm tuyến tính: Time Complexity: O(N) | Space Complexity: O(1)
export function linearSearch(arr: number[], target: number): number {
  // Duyệt qua N phần tử -> Trong trường hợp xấu nhất lặp N lần: O(N)
  // Bộ nhớ chỉ tốn 1 biến chỉ số i -> Auxiliary Space: O(1)
  for (let i = 0; i < arr.length; i++) {
    if (arr[i] === target) return i;
  }
  return -1;
}

// 2. Tìm kiếm nhị phân: Time Complexity: O(log N) | Space Complexity: O(1)
export function binarySearch(arr: number[], target: number): number {
  let left = 0;
  let right = arr.length - 1;
  // Mỗi bước chia đôi không gian tìm kiếm (N -> N/2 -> N/4 ...) -> O(log N)
  // Biến phụ trợ cố định left, right, mid -> Auxiliary Space: O(1)
  while (left <= right) {
    const mid = left + Math.floor((right - left) / 2);
    if (arr[mid] === target) return mid;
    if (arr[mid] < target) left = mid + 1;
    else right = mid - 1;
  }
  return -1;
}

// Tự triển khai Cấu trúc Dữ liệu Dynamic Array (Resizing Array) trong TypeScript
export class CustomDynamicArray<T> {
  private data: (T | undefined)[];
  private capacity: number;
  private length: number;

  constructor(initialCapacity = 4) {
    this.capacity = initialCapacity;
    this.length = 0;
    this.data = new Array(this.capacity);
  }

  // Time: Amortized O(1) | Worst-case O(N) khi trigger resize | Space: O(N)
  push(element: T): void {
    if (this.length === this.capacity) {
      this.resize(this.capacity * 2); // Nhân đôi dung lượng (Growth Factor = 2)
    }
    this.data[this.length++] = element;
  }

  // Time: O(1) ngẫu nhiên theo chỉ số | Space: O(1)
  get(index: number): T | undefined {
    if (index < 0 || index >= this.length) throw new RangeError('Index out of bounds');
    return this.data[index];
  }

  // Cơ chế cấp phát vùng nhớ mới và copy dữ liệu: Time O(N) | Space O(N)
  private resize(newCapacity: number): void {
    const newData = new Array(newCapacity);
    for (let i = 0; i < this.length; i++) {
      newData[i] = this.data[i];
    }
    this.data = newData;
    this.capacity = newCapacity;
  }

  size(): number { return this.length; }
}

// Triển khai Doubly Linked List Node và thao tác xóa node O(1) trong TypeScript
export class DoublyListNode<T> {
  value: T;
  next: DoublyListNode<T> | null = null;
  prev: DoublyListNode<T> | null = null;

  constructor(value: T) {
    this.value = value;
  }
}

export class DoublyLinkedList<T> {
  head: DoublyListNode<T> | null = null;
  tail: DoublyListNode<T> | null = null;

  // Thêm vào cuối: Time O(1) | Space O(1)
  append(value: T): DoublyListNode<T> {
    const newNode = new DoublyListNode(value);
    if (!this.tail) {
      this.head = this.tail = newNode;
    } else {
      this.tail.next = newNode;
      newNode.prev = this.tail;
      this.tail = newNode;
    }
    return newNode;
  }

  // Xóa một node bất kỳ đã có con trỏ tham chiếu: Time O(1) | Space O(1)
  removeNode(node: DoublyListNode<T>): void {
    if (node.prev) node.prev.next = node.next;
    else this.head = node.next; // Xóa head

    if (node.next) node.next.prev = node.prev;
    else this.tail = node.prev; // Xóa tail

    node.prev = null;
    node.next = null;
  }
}

// Triển khai Queue hiệu năng cao bằng Doubly Linked List / Circular Buffer O(1)
// (Tránh dùng JavaScript Array.shift() vì arr.shift() tốn O(N) time dịch mảng)
class QueueNode<T> {
  constructor(public value: T, public next: QueueNode<T> | null = null) {}
}

export class EfficientQueue<T> {
  private head: QueueNode<T> | null = null;
  private tail: QueueNode<T> | null = null;
  private count = 0;

  // Enqueue: Time O(1) | Space O(1)
  enqueue(val: T): void {
    const newNode = new QueueNode(val);
    if (!this.tail) {
      this.head = this.tail = newNode;
    } else {
      this.tail.next = newNode;
      this.tail = newNode;
    }
    this.count++;
  }

  // Dequeue: Time O(1) | Space O(1)
  dequeue(): T | undefined {
    if (!this.head) return undefined;
    const val = this.head.value;
    this.head = this.head.next;
    if (!this.head) this.tail = null;
    this.count--;
    return val;
  }

  size(): number { return this.count; }
}

// Triển khai Hash Table cơ bản sử dụng kỹ thuật Separate Chaining trong TypeScript
class HashNode<K, V> {
  constructor(public key: K, public value: V, public next: HashNode<K, V> | null = null) {}
}

export class SimpleHashTable<K, V> {
  private buckets: (HashNode<K, V> | null)[];
  private capacity: number;
  private size = 0;

  constructor(capacity = 16) {
    this.capacity = capacity;
    this.buckets = new Array(capacity).fill(null);
  }

  // Hàm băm đơn giản chuyển key thành index: O(1)
  private hash(key: K): number {
    const str = String(key);
    let hashVal = 0;
    for (let i = 0; i < str.length; i++) {
      hashVal = (hashVal * 31 + str.charCodeAt(i)) >>> 0;
    }
    return hashVal % this.capacity;
  }

  // Put: Average O(1) | Worst O(N) khi có collision sâu | Space O(1)
  set(key: K, value: V): void {
    const idx = this.hash(key);
    let head = this.buckets[idx];

    while (head) {
      if (head.key === key) {
        head.value = value; // Update value nếu key đã tồn tại
        return;
      }
      head = head.next;
    }

    // Chèn node mới vào đầu danh sách (Separate Chaining)
    const newNode = new HashNode(key, value, this.buckets[idx]);
    this.buckets[idx] = newNode;
    this.size++;
  }

  // Get: Average O(1) | Worst O(N)
  get(key: K): V | undefined {
    const idx = this.hash(key);
    let head = this.buckets[idx];
    while (head) {
      if (head.key === key) return head.value;
      head = head.next;
    }
    return undefined;
  }
}

// Thuật toán Binary Search chuẩn mực (Lower Bound: tìm vị trí đầu tiên >= target)
// Time Complexity: O(log N) | Space Complexity: O(1)
export function lowerBoundBinarySearch(arr: number[], target: number): number {
  let low = 0;
  let high = arr.length - 1;
  let ans = -1;

  while (low <= high) {
    // Tránh lỗi tràn số nguyên an toàn: low + (high - low) / 2
    const mid = low + Math.floor((high - low) / 2);

    if (arr[mid] >= target) {
      ans = mid;        // Ghi nhận đáp án tiềm năng
      high = mid - 1;   // Tiếp tục thu hẹp tìm kiếm về nửa bên trái
    } else {
      low = mid + 1;    // Target nằm ở nửa bên phải
    }
  }

  return ans; // Trả về index đầu tiên >= target hoặc -1 nếu không có
}

// Ứng dụng: arr = [1, 2, 4, 4, 4, 6, 9], target = 4 -> Trả về index = 2

// 1. Đệ quy thông thường: Tốn O(N) Call Stack Frames -> Dễ bị Stack Overflow nếu N lớn
export function recursiveFactorial(n: number): number {
  if (n <= 1) return 1; // Base condition bắt buộc
  return n * recursiveFactorial(n - 1); // Stack frame phải giữ lại để thực hiện phép nhân
}

// 2. Chuyển đổi sang Vòng lặp (Iterative): Time O(N) | Space O(1) -> Miễn nhiễm 100% với Stack Overflow!
export function iterativeFactorial(n: number): number {
  let result = 1;
  for (let i = 2; i <= n; i++) {
    result *= i;
  }
  return result; // Hoàn toàn không tốn thêm Stack Frame nào!
}

// Triển khai Insertion Sort tối ưu (Stable, Adaptive O(N) cho nearly-sorted data)
// Time: Best O(N) | Average/Worst O(N^2) | Space: O(1) In-place
export function insertionSort(arr: number[]): number[] {
  const n = arr.length;

  for (let i = 1; i < n; i++) {
    const current = arr[i];
    let j = i - 1;

    // Dời các phần tử lớn hơn 'current' sang phải 1 vị trí
    while (j >= 0 && arr[j] > current) {
      arr[j + 1] = arr[j];
      j--;
    }
    // Chèn 'current' vào vị trí trống thích hợp
    arr[j + 1] = current;
  }

  return arr;
}

// Định nghĩa Node cây nhị phân và 3 phương thức duyệt cây kinh điển bằng TypeScript
export class TreeNode {
  val: number;
  left: TreeNode | null = null;
  right: TreeNode | null = null;
  constructor(val: number) { this.val = val; }
}

// 1. Inorder Traversal (Left -> Root -> Right): Time O(N) | Space O(H)
// Trên BST: Trả về mảng số tăng dần có thứ tự
export function inorderTraversal(root: TreeNode | null): number[] {
  const result: number[] = [];
  function traverse(node: TreeNode | null) {
    if (!node) return;
    traverse(node.left);        // Left
    result.push(node.val);      // Root
    traverse(node.right);       // Right
  }
  traverse(root);
  return result;
}

// 2. Preorder Traversal (Root -> Left -> Right): Time O(N) | Space O(H)
export function preorderTraversal(root: TreeNode | null): number[] {
  const result: number[] = [];
  function traverse(node: TreeNode | null) {
    if (!node) return;
    result.push(node.val);      // Root
    traverse(node.left);        // Left
    traverse(node.right);       // Right
  }
  traverse(root);
  return result;
}

// 3. Postorder Traversal (Left -> Right -> Root): Time O(N) | Space O(H)
export function postorderTraversal(root: TreeNode | null): number[] {
  const result: number[] = [];
  function traverse(node: TreeNode | null) {
    if (!node) return;
    traverse(node.left);        // Left
    traverse(node.right);       // Right
    result.push(node.val);      // Root
  }
  traverse(root);
  return result;
}

// Thuật toán Two Pointers tìm cặp số có tổng bằng target trên mảng đã sắp xếp
// Time Complexity: O(N) | Space Complexity: O(1) In-place
export function twoSumSorted(numbers: number[], target: number): [number, number] | null {
  let left = 0;
  let right = numbers.length - 1;

  // Hai con trỏ di chuyển ngược chiều nhau cho đến khi gặp nhau
  while (left < right) {
    const currentSum = numbers[left] + numbers[right];

    if (currentSum === target) {
      return [left, right]; // Tìm thấy cặp index thỏa mãn: O(1) space
    } else if (currentSum < target) {
      // Tổng quá nhỏ -> Cần tăng giá trị bằng cách dịch con trỏ trái sang phải
      left++;
    } else {
      // Tổng quá lớn -> Cần giảm giá trị bằng cách dịch con trỏ phải sang trái
      right--;
    }
  }

  return null; // Không tồn tại cặp số
}

// Ví dụ: numbers = [2, 7, 11, 15], target = 9 -> Trả về [0, 1] (2 + 7 = 9) trong O(N) time!

// Bài toán kinh điển: Tìm độ dài chuỗi con dài nhất không chứa ký tự lặp lại (Dynamic Window)
// Time Complexity: O(N) | Space Complexity: O(min(N, M)) với M là kích thước bảng ký tự
export function lengthOfLongestSubstring(s: string): number {
  const charMap = new Map<string, number>(); // Lưu ký tự -> index xuất hiện gần nhất
  let maxLength = 0;
  let left = 0; // Cạnh trái của cửa sổ

  // Cạnh phải của cửa sổ trượt liên tục mở rộng
  for (let right = 0; right < s.length; right++) {
    const currentChar = s[right];

    // Nếu ký tự đã xuất hiện bên trong cửa sổ hiện tại -> Co cạnh trái vượt qua vị trí trùng lặp cũ
    if (charMap.has(currentChar) && charMap.get(currentChar)! >= left) {
      left = charMap.get(currentChar)! + 1;
    }

    charMap.set(currentChar, right); // Cập nhật index mới nhất của ký tự
    // Cập nhật độ dài lớn nhất của cửa sổ hợp lệ: (right - left + 1)
    maxLength = Math.max(maxLength, right - left + 1);
  }

  return maxLength;
}

// Test: s = "abcabcbb" -> chuỗi con "abc" có độ dài lớn nhất là 3

// Thuật toán Floyd's Cycle Detection: Phát hiện và trả về Node bắt đầu chu trình
// Time Complexity: O(N) | Space Complexity: O(1) Tuyệt đối
export class ListNode {
  val: number;
  next: ListNode | null = null;
  constructor(val: number) { this.val = val; }
}

export function detectCycle(head: ListNode | null): ListNode | null {
  if (!head || !head.next) return null;

  let slow: ListNode | null = head;
  let fast: ListNode | null = head;

  // Giai đoạn 1: Xác định danh sách có chu trình không (Fast đi 2 bước, Slow đi 1 bước)
  while (fast && fast.next) {
    slow = slow!.next;
    fast = fast.next.next;

    if (slow === fast) {
      // Giai đoạn 2: Tìm điểm bắt đầu chu trình
      // Đặt pointer1 về head, pointer2 giữ nguyên tại điểm gặp nhau
      let ptr1: ListNode | null = head;
      let ptr2: ListNode | null = slow;

      // Cả 2 cùng đi với tốc độ 1 bước -> Gặp nhau tại Node bắt đầu chu trình!
      while (ptr1 !== ptr2) {
        ptr1 = ptr1!.next;
        ptr2 = ptr2!.next;
      }
      return ptr1; // Trả về Cycle Start Node
    }
  }

  return null; // Không có chu trình
}

// Triển khai Merge Sort chuẩn mực (Chia để trị & Stable Sort)
// Time Complexity: O(N log N) trong MỌI trường hợp | Space Complexity: O(N)
export function mergeSort(arr: number[]): number[] {
  if (arr.length <= 1) return arr;

  const mid = Math.floor(arr.length / 2);
  const leftSorted = mergeSort(arr.slice(0, mid));
  const rightSorted = mergeSort(arr.slice(mid));

  return merge(leftSorted, rightSorted);
}

function merge(left: number[], right: number[]): number[] {
  const result: number[] = [];
  let i = 0;
  let j = 0;

  // Hợp nhất 2 mảng con có thứ tự (Bảo toàn tính ổn định với toán tử <=)
  while (i < left.length && j < right.length) {
    if (left[i] <= right[j]) {
      result.push(left[i++]);
    } else {
      result.push(right[j++]);
    }
  }

  // Nối phần tử còn dư
  while (i < left.length) result.push(left[i++]);
  while (j < right.length) result.push(right[j++]);

  return result;
}

// Triển khai Min-Heap chuẩn mực bằng mảng phẳng trong TypeScript
export class MinHeap {
  private heap: number[] = [];

  // Time: O(log N) | Space: O(1)
  push(val: number): void {
    this.heap.push(val);
    this.siftUp(this.heap.length - 1);
  }

  // Time: O(log N) | Space: O(1)
  pop(): number | undefined {
    if (this.heap.length === 0) return undefined;
    const minVal = this.heap[0];
    const endVal = this.heap.pop()!;
    if (this.heap.length > 0) {
      this.heap[0] = endVal;
      this.siftDown(0);
    }
    return minVal;
  }

  peek(): number | undefined { return this.heap[0]; }
  size(): number { return this.heap.length; }

  private siftUp(idx: number): void {
    while (idx > 0) {
      const parentIdx = Math.floor((idx - 1) / 2);
      if (this.heap[idx] < this.heap[parentIdx]) {
        [this.heap[idx], this.heap[parentIdx]] = [this.heap[parentIdx], this.heap[idx]];
        idx = parentIdx;
      } else break;
    }
  }

  private siftDown(idx: number): void {
    const len = this.heap.length;
    while (2 * idx + 1 < len) {
      let smallest = 2 * idx + 1; // Left child
      const right = smallest + 1;
      if (right < len && this.heap[right] < this.heap[smallest]) smallest = right;

      if (this.heap[idx] > this.heap[smallest]) {
        [this.heap[idx], this.heap[smallest]] = [this.heap[smallest], this.heap[idx]];
        idx = smallest;
      } else break;
    }
  }
}

// Ứng dụng: Tìm K phần tử lớn nhất từ mảng N phần tử: Time O(N log K) | Space O(K)
export function findTopKLargest(nums: number[], k: number): number[] {
  const minHeap = new MinHeap();
  for (const num of nums) {
    minHeap.push(num);
    if (minHeap.size() > k) minHeap.pop(); // Giữ kích thước heap luôn bằng K
  }
  const result: number[] = [];
  while (minHeap.size() > 0) result.push(minHeap.pop()!);
  return result; // K phần tử lớn nhất
}

// Biểu diễn Đồ thị bằng Danh sách kề (Adjacency List) tối ưu cho Sparse Graph trong TypeScript
export class GraphAdjacencyList {
  private adjList: Map<number, number[]> = new Map();

  // Khởi tạo đỉnh: Time O(1)
  addVertex(v: number): void {
    if (!this.adjList.has(v)) this.adjList.set(v, []);
  }

  // Thêm cạnh vô hướng: Time O(1) | Space O(E)
  addEdge(u: number, v: number): void {
    this.addVertex(u);
    this.addVertex(v);
    this.adjList.get(u)!.push(v);
    this.adjList.get(v)!.push(u);
  }

  // Lấy danh sách hàng xóm của đỉnh u: Time O(1)
  getNeighbors(u: number): number[] {
    return this.adjList.get(u) || [];
  }

  // Kiểm tra cạnh (u, v) có tồn tại không: Time O(deg(u))
  hasEdge(u: number, v: number): boolean {
    const neighbors = this.adjList.get(u);
    return neighbors ? neighbors.includes(v) : false;
  }
}

// Thuật toán BFS tìm đường đi ngắn nhất (Shortest Path) trên đồ thị không trọng số bằng TypeScript
export function bfsShortestPath(
  adjList: Map<number, number[]>,
  startNode: number,
  targetNode: number
): number[] | null {
  if (startNode === targetNode) return [startNode];

  const queue: number[] = [startNode];
  const visited = new Set<number>([startNode]);
  // Map lưu vết: parentMap.set(child, parent) để truy vết lại đường đi
  const parentMap = new Map<number, number>();

  while (queue.length > 0) {
    const current = queue.shift()!;

    if (current === targetNode) {
      // Tìm thấy đích -> Tái dựng lại đường đi từ target ngược về start
      const path: number[] = [];
      let curr: number | undefined = targetNode;
      while (curr !== undefined) {
        path.push(curr);
        curr = parentMap.get(curr);
      }
      return path.reverse(); // Đảo ngược để có đường từ start -> target
    }

    const neighbors = adjList.get(current) || [];
    for (const neighbor of neighbors) {
      if (!visited.has(neighbor)) {
        visited.add(neighbor);
        parentMap.set(neighbor, current);
        queue.push(neighbor); // Duyệt theo tầng (Level order)
      }
    }
  }

  return null; // Không có đường đi
}

// Triển khai thao tác Xóa (Delete) chuẩn mực trên Cây Tìm Kiếm Nhị Phân (BST)
export class TreeNode {
  val: number;
  left: TreeNode | null = null;
  right: TreeNode | null = null;
  constructor(val: number) { this.val = val; }
}

// Time: Average O(log N) | Worst-case O(N) | Space: O(H) Call Stack
export function deleteNode(root: TreeNode | null, key: number): TreeNode | null {
  if (!root) return null;

  if (key < root.val) {
    root.left = deleteNode(root.left, key);
  } else if (key > root.val) {
    root.right = deleteNode(root.right, key);
  } else {
    // Tìm thấy node cần xóa (root.val === key)
    // Trường hợp 1 & 2: Node có 0 hoặc 1 con
    if (!root.left) return root.right;
    if (!root.right) return root.left;

    // Trường hợp 3: Node có đủ 2 con -> Tìm Inorder Successor (nhỏ nhất cây con phải)
    let successor = root.right;
    while (successor.left) {
      successor = successor.left;
    }
    // Gán giá trị của successor vào node hiện tại
    root.val = successor.val;
    // Xóa successor khỏi cây con bên phải
    root.right = deleteNode(root.right, successor.val);
  }

  return root;
}

// Triển khai thao tác Xoay Phải (Right Rotation) và Xoay Trái (Left Rotation) trong TypeScript
export class AvlNode {
  val: number;
  left: AvlNode | null = null;
  right: AvlNode | null = null;
  height = 1;
  constructor(val: number) { this.val = val; }
}

export class TreeRotator {
  // Xoay Phải (Right Rotation): Time O(1) | Space O(1)
  static rotateRight(y: AvlNode): AvlNode {
    const x = y.left!;
    const T2 = x.right;

    // Thực hiện xoay
    x.right = y;
    y.left = T2;

    // Cập nhật lại chiều cao của các node
    y.height = Math.max(this.getHeight(y.left), this.getHeight(y.right)) + 1;
    x.height = Math.max(this.getHeight(x.left), this.getHeight(x.right)) + 1;

    return x; // x trở thành root mới của cây con
  }

  // Xoay Trái (Left Rotation): Time O(1) | Space O(1)
  static rotateLeft(x: AvlNode): AvlNode {
    const y = x.right!;
    const T2 = y.left;

    y.left = x;
    x.right = T2;

    x.height = Math.max(this.getHeight(x.left), this.getHeight(x.right)) + 1;
    y.height = Math.max(this.getHeight(y.left), this.getHeight(y.right)) + 1;

    return y; // y trở thành root mới
  }

  private static getHeight(node: AvlNode | null): number {
    return node ? node.height : 0;
  }
}

// Triển khai Cây Tiền Tố (Trie) và tính năng Auto-complete trong TypeScript
class TrieNode {
  children: Map<string, TrieNode> = new Map();
  isEndOfWord = false;
}

export class Trie {
  private root = new TrieNode();

  // Chèn một từ vào Trie: Time O(L) | Space O(L) với L là độ dài từ
  insert(word: string): void {
    let curr = this.root;
    for (const char of word) {
      if (!curr.children.has(char)) {
        curr.children.set(char, new TrieNode());
      }
      curr = curr.children.get(char)!;
    }
    curr.isEndOfWord = true;
  }

  // Auto-complete: Gợi ý các từ bắt đầu bằng prefix: Time O(P + K) với P là độ dài prefix
  autocomplete(prefix: string, maxResults = 5): string[] {
    let curr = this.root;
    // 1. Đi theo tiền tố prefix
    for (const char of prefix) {
      if (!curr.children.has(char)) return [];
      curr = curr.children.get(char)!;
    }

    // 2. Duyệt DFS gom các từ hoàn chỉnh từ node hiện tại
    const results: string[] = [];
    const dfs = (node: TrieNode, currentWord: string) => {
      if (results.length >= maxResults) return;
      if (node.isEndOfWord) results.push(currentWord);

      for (const [char, childNode] of node.children.entries()) {
        dfs(childNode, currentWord + char);
      }
    };

    dfs(curr, prefix);
    return results;
  }
}

// Khung mẫu chuẩn (Backtracking Template) giải bài toán Sinh Hoán Vị (Permutations)
// Time Complexity: O(N * N!) | Space Complexity: O(N) Call Stack
export function permute(nums: number[]): number[][] {
  const results: number[][] = [];
  const currentPath: number[] = [];
  const used = new Array(nums.length).fill(false);

  function backtrack() {
    // 1. Base Condition: Đã chọn đủ N phần tử -> Ghi nhận 1 hoán vị hoàn chỉnh
    if (currentPath.length === nums.length) {
      results.push([...currentPath]); // Clone mảng nghiệm
      return;
    }

    for (let i = 0; i < nums.length; i++) {
      if (used[i]) continue; // Cắt tỉa: Bỏ qua phần tử đã được chọn

      // BƯỚC 1: CHOOSE (Đưa ra lựa chọn)
      used[i] = true;
      currentPath.push(nums[i]);

      // BƯỚC 2: EXPLORE (Đệ quy đi sâu)
      backtrack();

      // BƯỚC 3: UNCHOOSE (Quay lui, khôi phục trạng thái)
      currentPath.pop();
      used[i] = false;
    }
  }

  backtrack();
  return results;
}

// Bài toán Next Greater Element bằng Monotonic Decreasing Stack trong TypeScript
// Time Complexity: O(N) Tuyến tính | Space Complexity: O(N)
export function nextGreaterElements(nums: number[]): number[] {
  const n = nums.length;
  const result: number[] = new Array(n).fill(-1);
  const stack: number[] = []; // Lưu các CHỈ SỐ (Indices) có giá trị giảm dần

  for (let i = 0; i < n; i++) {
    // Trong khi stack không rỗng và phần tử hiện tại lớn hơn giá trị đỉnh stack
    while (stack.length > 0 && nums[i] > nums[stack[stack.length - 1]]) {
      const poppedIdx = stack.pop()!;
      result[poppedIdx] = nums[i]; // nums[i] chính là phần tử lớn hơn tiếp theo!
    }
    stack.push(i); // Đẩy index hiện tại vào stack
  }

  return result;
}

// Test: nums = [2, 1, 2, 4, 3] -> result = [4, 2, 4, -1, -1] trong O(N) time!

// Triển khai Cấu trúc Dữ liệu Union-Find (DSU) tối ưu chuẩn mực trong TypeScript
export class DisjointSetUnion {
  private parent: number[];
  private rank: number[];

  constructor(size: number) {
    this.parent = new Array(size);
    this.rank = new Array(size).fill(0);
    // Ban đầu mỗi phần tử là cha của chính nó
    for (let i = 0; i < size; i++) this.parent[i] = i;
  }

  // Find với Path Compression: Time O(α(N)) ≈ O(1)
  find(x: number): number {
    if (this.parent[x] !== x) {
      // Nén đường đi: Gán trực tiếp node cha thành root
      this.parent[x] = this.find(this.parent[x]);
    }
    return this.parent[x];
  }

  // Union by Rank: Time O(α(N)) ≈ O(1)
  union(x: number, y: number): boolean {
    const rootX = this.find(x);
    const rootY = this.find(y);

    if (rootX === rootY) return false; // Đã cùng một tập hợp (Phát hiện chu trình)

    // Gắn cây có rank thấp hơn vào dưới gốc cây có rank cao hơn
    if (this.rank[rootX] < this.rank[rootY]) {
      this.parent[rootX] = rootY;
    } else if (this.rank[rootX] > this.rank[rootY]) {
      this.parent[rootY] = rootX;
    } else {
      this.parent[rootY] = rootX;
      this.rank[rootX]++; // Chiều cao tăng 1 khi 2 cây cùng rank
    }

    return true; // Gộp thành công
  }
}

// So sánh 2 cách giải bài toán Số bước nhảy Fibonacci (Climbing Stairs)
// 1. TOP-DOWN VỚI MEMOIZATION: Time O(N) | Space O(N) (Memo + Call Stack)
export function climbStairsTopDown(n: number, memo = new Map<number, number>()): number {
  if (n <= 2) return n;
  if (memo.has(n)) return memo.get(n)!; // Tận dụng cache memoization

  const res = climbStairsTopDown(n - 1, memo) + climbStairsTopDown(n - 2, memo);
  memo.set(n, res);
  return res;
}

// 2. BOTTOM-UP VỚI TABULATION & SPACE OPTIMIZATION: Time O(N) | Space O(1) Tuyệt đối
export function climbStairsBottomUp(n: number): number {
  if (n <= 2) return n;

  // Base cases: Khởi tạo từ các bài toán con nhỏ nhất
  let prev2 = 1; // n = 1
  let prev1 = 2; // n = 2

  for (let i = 3; i <= n; i++) {
    const current = prev1 + prev2; // dp[i] = dp[i-1] + dp[i-2]
    prev2 = prev1;
    prev1 = current;
  }

  return prev1; // Đáp án tối ưu chỉ tốn 2 biến phụ trợ: Space O(1)!
}

// Minh họa: Phân tích bài toán Coin Change (Đổi tiền ít xu nhất) thỏa mãn 2 thuộc tính DP
// Time Complexity: O(Amount * Coins.length) | Space Complexity: O(Amount)
export function coinChange(coins: number[], amount: number): number {
  // dp[i] là số đồng xu ít nhất để đổi được số tiền i
  // 1. Cấu trúc con tối ưu: dp[i] = 1 + min(dp[i - coin]) với mọi coin <= i
  // 2. Bài toán con gối nhau: Việc đổi số tiền (i - coin) được lặp lại hàng trăm lần
  const dp = new Array(amount + 1).fill(Infinity);
  dp[0] = 0; // Base case: 0 tiền cần 0 xu

  for (let i = 1; i <= amount; i++) {
    for (const coin of coins) {
      if (i - coin >= 0) {
        dp[i] = Math.min(dp[i], dp[i - coin] + 1);
      }
    }
  }

  return dp[amount] === Infinity ? -1 : dp[amount];
}

// Triển khai bài toán Balo 0/1 tối ưu không gian mảng 1 chiều (Space-optimized 1D Array)
// Time Complexity: O(N * W) | Space Complexity: O(W) Tuyệt đối
export function knapsack01(weights: number[], values: number[], capacity: number): number {
  const n = weights.length;
  // dp[w] lưu giá trị lớn nhất đạt được với sức chứa w
  const dp = new Array(capacity + 1).fill(0);

  for (let i = 0; i < n; i++) {
    const currentWeight = weights[i];
    const currentValue = values[i];

    // QUY TẮC SỐNG CÒN: Duyệt NGƯỢC từ capacity về currentWeight
    for (let w = capacity; w >= currentWeight; w--) {
      dp[w] = Math.max(dp[w], currentValue + dp[w - currentWeight]);
    }
  }

  return dp[capacity];
}

// Test: weights = [1, 3, 4], values = [15, 20, 30], capacity = 4 -> dp = 35 (chọn vật 1 và 2: wt 1+3=4, val 15+20=35)

// Thuật toán LIS tối ưu đỉnh cao: Time O(N log N) | Space O(N)
export function lengthOfLIS(nums: number[]): number {
  if (nums.length === 0) return 0;

  // tails[i] lưu phần tử kết thúc nhỏ nhất của dãy con tăng độ dài i + 1
  const tails: number[] = [];

  for (const num of nums) {
    // Tìm vị trí phần tử đầu tiên trong tails >= num bằng Binary Search
    let left = 0;
    let right = tails.length - 1;
    let insertIdx = tails.length;

    while (left <= right) {
      const mid = left + Math.floor((right - left) / 2);
      if (tails[mid] >= num) {
        insertIdx = mid;
        right = mid - 1; // Tìm tiếp bên trái
      } else {
        left = mid + 1;
      }
    }

    // Cập nhật hoặc mở rộng mảng tails
    if (insertIdx === tails.length) {
      tails.push(num); // Mở rộng độ dài LIS
    } else {
      tails[insertIdx] = num; // Thay thế bằng giá trị nhỏ hơn tối ưu
    }
  }

  return tails.length; // Độ dài của tails chính là độ dài của LIS!
}

// Test: nums = [10, 9, 2, 5, 3, 7, 101, 18] -> LIS = [2, 3, 7, 101] -> length = 4

// Triển khai thuật toán LCS và truy vết sinh chuỗi Diff tương tự 'git diff'
// Time Complexity: O(M * N) | Space Complexity: O(M * N)
export function computeLcsDiff(oldLines: string[], newLines: string[]): string[] {
  const m = oldLines.length;
  const n = newLines.length;

  // 1. Điền bảng DP 2 chiều
  const dp: number[][] = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (oldLines[i - 1] === newLines[j - 1]) {
        dp[i][j] = 1 + dp[i - 1][j - 1];
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
      }
    }
  }

  // 2. Truy vết ngược (Backtracking) để tạo ra các dòng diff (+/-)
  const diffOutput: string[] = [];
  let i = m;
  let j = n;

  while (i > 0 || j > 0) {
    if (i > 0 && j > 0 && oldLines[i - 1] === newLines[j - 1]) {
      diffOutput.push(`  ${oldLines[i - 1]}`); // Giữ nguyên (LCS line)
      i--;
      j--;
    } else if (j > 0 && (i === 0 || dp[i][j - 1] >= dp[i - 1][j])) {
      diffOutput.push(`+ ${newLines[j - 1]}`); // Dòng được thêm mới
      j--;
    } else if (i > 0 && (j === 0 || dp[i][j - 1] < dp[i - 1][j])) {
      diffOutput.push(`- ${oldLines[i - 1]}`); // Dòng bị xóa
      i--;
    }
  }

  return diffOutput.reverse();
}

// Thuật toán Kadane tìm tổng lớn nhất và chỉ số bắt đầu/kết thúc của mảng con
// Time Complexity: O(N) | Space Complexity: O(1) Tuyệt đối
export function maxSubArrayKadane(nums: number[]): { maxSum: number; start: number; end: number } {
  let maxSum = nums[0];
  let currentSum = nums[0];

  let start = 0;
  let end = 0;
  let tempStart = 0;

  for (let i = 1; i < nums.length; i++) {
    // Nếu currentSum < 0 -> Bắt đầu mảng con mới từ i
    if (nums[i] > currentSum + nums[i]) {
      currentSum = nums[i];
      tempStart = i;
    } else {
      currentSum += nums[i];
    }

    // Cập nhật kỷ lục tổng lớn nhất toàn cục
    if (currentSum > maxSum) {
      maxSum = currentSum;
      start = tempStart;
      end = i;
    }
  }

  return { maxSum, start, end };
}

// Test: nums = [-2, 1, -3, 4, -1, 2, 1, -5, 4] -> mảng con [4, -1, 2, 1] có maxSum = 6

// Triển khai Counting Sort ổn định (Stable Sort) cho mảng số nguyên không âm
// Time Complexity: O(N + K) | Space Complexity: O(N + K) với K là giá trị lớn nhất
export function countingSort(arr: number[]): number[] {
  if (arr.length <= 1) return arr;

  const maxVal = Math.max(...arr);
  const count = new Array(maxVal + 1).fill(0);
  const output = new Array(arr.length);

  // 1. Đếm tần suất xuất hiện của từng giá trị: O(N)
  for (const num of arr) count[num]++;

  // 2. Tính tổng tiền tố tích lũy để xác định vị trí index cuối cùng của mỗi phần tử: O(K)
  for (let i = 1; i <= maxVal; i++) {
    count[i] += count[i - 1];
  }

  // 3. Duyệt NGƯỢC mảng ban đầu để bảo toàn tính ổn định (Stability): O(N)
  for (let i = arr.length - 1; i >= 0; i--) {
    const val = arr[i];
    output[count[val] - 1] = val;
    count[val]--;
  }

  return output;
}

// Triển khai cả 2 phương pháp Đảo ngược Danh sách liên kết trong TypeScript
export class ListNode {
  val: number;
  next: ListNode | null = null;
  constructor(val: number) { this.val = val; }
}

// 1. PHƯƠNG PHÁP LẶP (ITERATIVE) - CHUẨN MỰC SENIOR
// Time Complexity: O(N) | Space Complexity: O(1) Tuyệt đối
export function reverseListIterative(head: ListNode | null): ListNode | null {
  let prev: ListNode | null = null;
  let curr: ListNode | null = head;

  while (curr !== null) {
    const nextTemp: ListNode | null = curr.next; // Lưu tạm con trỏ tiếp theo
    curr.next = prev;     // Bẻ ngược chiều liên kết về phía sau
    prev = curr;          // Tiến con trỏ prev lên
    curr = nextTemp;      // Tiến con trỏ curr lên
  }

  return prev; // prev trở thành Head mới của danh sách đảo ngược
}

// 2. PHƯƠNG PHÁP ĐỆ QUY (RECURSIVE)
// Time Complexity: O(N) | Space Complexity: O(N) Call Stack Frames
export function reverseListRecursive(head: ListNode | null): ListNode | null {
  // Base case: Danh sách rỗng hoặc chỉ có 1 node
  if (!head || !head.next) return head;

  // Đệ quy sâu đến node cuối cùng
  const newHead = reverseListRecursive(head.next);

  // Đảo ngược liên kết tại bước hiện tại
  head.next.next = head; // Node phía sau trỏ ngược lại node hiện tại
  head.next = null;      // Cắt đứt liên kết xuôi cũ để chống tạo chu trình

  return newHead;
}

// Triển khai thuật toán Dijkstra sử dụng Min-Heap trong TypeScript
// Time Complexity: O((V + E) log V) | Space Complexity: O(V + E)
interface Edge { node: number; weight: number; }

export function dijkstra(
  graph: Map<number, Edge[]>,
  source: number,
  numVertices: number
): number[] {
  const dist = new Array(numVertices).fill(Infinity);
  dist[source] = 0;

  // Min-Heap lưu cặp [distance, node]
  // Trong production dùng Heap chuẩn; ở đây dùng mảng sắp xếp mô phỏng priority queue logic
  const pq: [number, number][] = [[0, source]];

  while (pq.length > 0) {
    // Bốc đỉnh có khoảng cách nhỏ nhất
    pq.sort((a, b) => a[0] - b[0]);
    const [currentDist, u] = pq.shift()!;

    // Bỏ qua nếu đã tìm được đường đi ngắn hơn đến u trước đó (Lazy Deletion)
    if (currentDist > dist[u]) continue;

    const neighbors = graph.get(u) || [];
    for (const edge of neighbors) {
      const v = edge.node;
      const weight = edge.weight;

      // Bước Nới Lỏng (Edge Relaxation)
      if (dist[u] + weight < dist[v]) {
        dist[v] = dist[u] + weight;
        pq.push([dist[v], v]);
      }
    }
  }

  return dist;
}

// Thuật toán Bellman-Ford tìm đường đi ngắn nhất và phát hiện Chu trình âm
// Time Complexity: O(V * E) | Space Complexity: O(V)
export interface DirectedEdge {
  from: number;
  to: number;
  weight: number;
}

export function bellmanFord(
  edges: DirectedEdge[],
  numVertices: number,
  source: number
): { dist: number[]; hasNegativeCycle: boolean } {
  const dist = new Array(numVertices).fill(Infinity);
  dist[source] = 0;

  // Bước 1: Nới lỏng toàn bộ các cạnh V - 1 lần
  for (let i = 1; i <= numVertices - 1; i++) {
    let updated = false;
    for (const { from, to, weight } of edges) {
      if (dist[from] !== Infinity && dist[from] + weight < dist[to]) {
        dist[to] = dist[from] + weight;
        updated = true;
      }
    }
    // Tối ưu hóa: Nếu 1 vòng lặp không có cạnh nào được nới lỏng -> Dừng sớm
    if (!updated) break;
  }

  // Bước 2: Kiểm tra Chu trình âm ở lần lặp thứ V
  let hasNegativeCycle = false;
  for (const { from, to, weight } of edges) {
    if (dist[from] !== Infinity && dist[from] + weight < dist[to]) {
      hasNegativeCycle = true; // Phát hiện chu trình âm!
      break;
    }
  }

  return { dist, hasNegativeCycle };
}

// Giải bài toán Course Schedule II (Tìm thứ tự học môn) bằng thuật toán Kahn (BFS In-degree)
// Time Complexity: O(V + E) | Space Complexity: O(V + E)
export function findOrderTopological(numCourses: number, prerequisites: [number, number][]): number[] {
  const inDegree = new Array(numCourses).fill(0);
  const adjList = new Map<number, number[]>();

  // 1. Xây dựng đồ thị và tính In-degree của từng đỉnh
  for (const [course, prereq] of prerequisites) {
    // Cạnh có hướng: prereq -> course (phải học prereq trước)
    if (!adjList.has(prereq)) adjList.set(prereq, []);
    adjList.get(prereq)!.push(course);
    inDegree[course]++;
  }

  // 2. Đưa các môn học không có điều kiện tiên quyết (inDegree = 0) vào Queue
  const queue: number[] = [];
  for (let i = 0; i < numCourses; i++) {
    if (inDegree[i] === 0) queue.push(i);
  }

  const order: number[] = [];

  // 3. Xử lý BFS theo bán bậc vào
  while (queue.length > 0) {
    const curr = queue.shift()!;
    order.push(curr);

    const neighbors = adjList.get(curr) || [];
    for (const nextCourse of neighbors) {
      inDegree[nextCourse]--;
      // Nếu đã hoàn thành mọi môn tiên quyết -> Đưa vào queue
      if (inDegree[nextCourse] === 0) {
        queue.push(nextCourse);
      }
    }
  }

  // Nếu số môn học xếp được < tổng số môn -> Có chu trình phụ thuộc vòng tròn!
  return order.length === numCourses ? order : [];
}

// Triển khai thuật toán Kruskal tìm Cây khung nhỏ nhất (MST) dùng DSU trong TypeScript
// Time Complexity: O(E log E) | Space Complexity: O(V + E)
interface GraphEdge { u: number; v: number; weight: number; }

export function kruskalMST(numVertices: number, edges: GraphEdge[]): { totalWeight: number; mstEdges: GraphEdge[] } {
  // 1. Sắp xếp toàn bộ cạnh theo trọng số tăng dần: O(E log E)
  edges.sort((a, b) => a.weight - b.weight);

  // 2. Khởi tạo DSU quản lý tập đỉnh
  const parent = new Array(numVertices).fill(0).map((_, i) => i);
  const find = (x: number): number => (parent[x] === x ? x : (parent[x] = find(parent[x])));

  let totalWeight = 0;
  const mstEdges: GraphEdge[] = [];

  // 3. Duyệt qua từng cạnh nhỏ nhất và gộp tập hợp
  for (const edge of edges) {
    const rootU = find(edge.u);
    const rootV = find(edge.v);

    // Nếu u và v chưa liên thông -> Thêm cạnh vào MST (chống chu trình)
    if (rootU !== rootV) {
      parent[rootU] = rootV;
      totalWeight += edge.weight;
      mstEdges.push(edge);
      // Đủ V - 1 cạnh thì dừng sớm
      if (mstEdges.length === numVertices - 1) break;
    }
  }

  return { totalWeight, mstEdges };
}

// Triển khai LRU Cache hoàn chỉnh với HashMap và Doubly Linked List trong TypeScript
class DNode {
  key: number;
  val: number;
  prev: DNode | null = null;
  next: DNode | null = null;
  constructor(k = 0, v = 0) { this.key = k; this.val = v; }
}

export class LRUCache {
  private capacity: number;
  private map = new Map<number, DNode>();
  private head = new DNode(); // Dummy Head
  private tail = new DNode(); // Dummy Tail

  constructor(capacity: number) {
    this.capacity = capacity;
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  // Get: Time O(1) | Space O(1)
  get(key: number): number {
    const node = this.map.get(key);
    if (!node) return -1;
    this.moveToHead(node); // Đánh dấu vừa được sử dụng
    return node.val;
  }

  // Put: Time O(1) | Space O(1)
  put(key: number, value: number): void {
    const existingNode = this.map.get(key);
    if (existingNode) {
      existingNode.val = value;
      this.moveToHead(existingNode);
    } else {
      const newNode = new DNode(key, value);
      this.map.set(key, newNode);
      this.addToHead(newNode);

      if (this.map.size > this.capacity) {
        // Loại bỏ phần tử lâu nhất không dùng (ngay trước tail)
        const lruNode = this.tail.prev!;
        this.removeNode(lruNode);
        this.map.delete(lruNode.key);
      }
    }
  }

  private addNode(node: DNode): void {
    node.prev = this.head;
    node.next = this.head.next;
    this.head.next!.prev = node;
    this.head.next = node;
  }

  private removeNode(node: DNode): void {
    node.prev!.next = node.next;
    node.next!.prev = node.prev;
  }

  private moveToHead(node: DNode): void {
    this.removeNode(node);
    this.addNode(node);
  }

  private addToHead(node: DNode): void {
    this.addNode(node);
  }
}

// Cấu trúc LFU Cache đạt độ phức tạp O(1) hoàn hảo trong TypeScript
class LFUDNode {
  constructor(
    public key: number,
    public val: number,
    public freq: number = 1,
    public prev: LFUDNode | null = null,
    public next: LFUDNode | null = null
  ) {}
}

class DoublyList {
  head = new LFUDNode(0, 0);
  tail = new LFUDNode(0, 0);
  size = 0;
  constructor() {
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }
  addFirst(node: LFUDNode) {
    node.next = this.head.next;
    node.prev = this.head;
    this.head.next!.prev = node;
    this.head.next = node;
    this.size++;
  }
  remove(node: LFUDNode) {
    node.prev!.next = node.next;
    node.next!.prev = node.prev;
    this.size--;
  }
  removeLast(): LFUDNode | null {
    if (this.size === 0) return null;
    const last = this.tail.prev!;
    this.remove(last);
    return last;
  }
}

export class LFUCache {
  private keyMap = new Map<number, LFUDNode>();
  private freqMap = new Map<number, DoublyList>();
  private minFreq = 0;

  constructor(private capacity: number) {}

  get(key: number): number {
    const node = this.keyMap.get(key);
    if (!node) return -1;
    this.incrementFreq(node);
    return node.val;
  }

  put(key: number, value: number): void {
    if (this.capacity === 0) return;
    if (this.keyMap.has(key)) {
      const node = this.keyMap.get(key)!;
      node.val = value;
      this.incrementFreq(node);
    } else {
      if (this.keyMap.size >= this.capacity) {
        const minList = this.freqMap.get(this.minFreq)!;
        const evicted = minList.removeLast()!;
        this.keyMap.delete(evicted.key);
      }
      const newNode = new LFUDNode(key, value, 1);
      this.keyMap.set(key, newNode);
      if (!this.freqMap.has(1)) this.freqMap.set(1, new DoublyList());
      this.freqMap.get(1)!.addFirst(newNode);
      this.minFreq = 1;
    }
  }

  private incrementFreq(node: LFUDNode) {
    const oldFreq = node.freq;
    const oldList = this.freqMap.get(oldFreq)!;
    oldList.remove(node);
    if (oldList.size === 0 && this.minFreq === oldFreq) this.minFreq++;

    node.freq++;
    if (!this.freqMap.has(node.freq)) this.freqMap.set(node.freq, new DoublyList());
    this.freqMap.get(node.freq)!.addFirst(node);
  }
}

// Triển khai Cây Phân Đoạn (Segment Tree) hỗ trợ Range Sum Query và Point Update
export class SegmentTree {
  private tree: number[];
  private n: number;

  constructor(nums: number[]) {
    this.n = nums.length;
    this.tree = new Array(4 * this.n).fill(0);
    if (this.n > 0) this.build(nums, 1, 0, this.n - 1);
  }

  // Xây dựng cây: Time O(N) | Space O(4N)
  private build(nums: number[], node: number, start: number, end: number): void {
    if (start === end) {
      this.tree[node] = nums[start];
      return;
    }
    const mid = Math.floor((start + end) / 2);
    this.build(nums, 2 * node, start, mid);
    this.build(nums, 2 * node + 1, mid + 1, end);
    this.tree[node] = this.tree[2 * node] + this.tree[2 * node + 1];
  }

  // Cập nhật điểm tại index: Time O(log N)
  update(index: number, val: number, node = 1, start = 0, end = this.n - 1): void {
    if (start === end) {
      this.tree[node] = val;
      return;
    }
    const mid = Math.floor((start + end) / 2);
    if (index <= mid) this.update(index, val, 2 * node, start, mid);
    else this.update(index, val, 2 * node + 1, mid + 1, end);
    this.tree[node] = this.tree[2 * node] + this.tree[2 * node + 1];
  }

  // Truy vấn tổng khoảng [L, R]: Time O(log N)
  querySum(L: number, R: number, node = 1, start = 0, end = this.n - 1): number {
    if (R < start || end < L) return 0; // Nằm ngoài phạm vi
    if (L <= start && end <= R) return this.tree[node]; // Nằm gọn bên trong

    const mid = Math.floor((start + end) / 2);
    const leftSum = this.querySum(L, R, 2 * node, start, mid);
    const rightSum = this.querySum(L, R, 2 * node + 1, mid + 1, end);
    return leftSum + rightSum;
  }
}

// Triển khai Segment Tree với Lazy Propagation (Range Update & Range Sum Query O(log N))
export class LazySegmentTree {
  private tree: number[];
  private lazy: number[];

  constructor(private n: number) {
    this.tree = new Array(4 * n).fill(0);
    this.lazy = new Array(4 * n).fill(0);
  }

  // Đẩy giá trị cập nhật đang nợ xuống 2 node con (Push Down)
  private pushDown(node: number, start: number, end: number): void {
    if (this.lazy[node] !== 0) {
      const val = this.lazy[node];
      const mid = Math.floor((start + end) / 2);

      // Cập nhật cho con trái
      this.tree[2 * node] += val * (mid - start + 1);
      this.lazy[2 * node] += val;

      // Cập nhật cho con phải
      this.tree[2 * node + 1] += val * (end - mid);
      this.lazy[2 * node + 1] += val;

      this.lazy[node] = 0; // Đã trả nợ xong
    }
  }

  // Range Update: Cộng val vào tất cả phần tử trong đoạn [L, R] trong O(log N)
  updateRange(L: number, R: number, val: number, node = 1, start = 0, end = this.n - 1): void {
    if (R < start || end < L) return;

    if (L <= start && end <= R) {
      this.tree[node] += val * (end - start + 1);
      this.lazy[node] += val; // Đánh dấu nợ cho các node con
      return;
    }

    this.pushDown(node, start, end);
    const mid = Math.floor((start + end) / 2);
    this.updateRange(L, R, val, 2 * node, start, mid);
    this.updateRange(L, R, val, 2 * node + 1, mid + 1, end);
    this.tree[node] = this.tree[2 * node] + this.tree[2 * node + 1];
  }

  // Range Sum Query: O(log N)
  queryRange(L: number, R: number, node = 1, start = 0, end = this.n - 1): number {
    if (R < start || end < L) return 0;
    if (L <= start && end <= R) return this.tree[node];

    this.pushDown(node, start, end);
    const mid = Math.floor((start + end) / 2);
    return this.queryRange(L, R, 2 * node, start, mid) +
           this.queryRange(L, R, 2 * node + 1, mid + 1, end);
  }
}

// Triển khai Fenwick Tree (Binary Indexed Tree) chuẩn mực 1-indexed trong TypeScript
export class FenwickTree {
  private tree: number[];

  constructor(private size: number) {
    // Kích thước N + 1 vì BIT bắt buộc dùng 1-indexed
    this.tree = new Array(size + 1).fill(0);
  }

  // Cộng giá trị delta vào phần tử tại chỉ số i (1-indexed): Time O(log N)
  update(i: number, delta: number): void {
    while (i <= this.size) {
      this.tree[i] += delta;
      i += i & -i; // Nhảy tiến: Thêm bit 1 nhỏ nhất
    }
  }

  // Tính tổng tiền tố từ 1 đến i: Time O(log N)
  queryPrefixSum(i: number): number {
    let sum = 0;
    while (i > 0) {
      sum += this.tree[i];
      i -= i & -i; // Nhảy lùi: Xóa bit 1 nhỏ nhất
    }
    return sum;
  }

  // Tính tổng đoạn [L, R]: Time O(log N)
  queryRange(L: number, R: number): number {
    return this.queryPrefixSum(R) - this.queryPrefixSum(L - 1);
  }
}

// Thuật toán KMP Khớp Chuỗi Tuyến Tính trong TypeScript
// Time Complexity: O(N + M) | Space Complexity: O(M)
export function kmpSearch(text: string, pattern: string): number[] {
  const n = text.length;
  const m = pattern.length;
  if (m === 0) return [];

  // 1. Xây dựng bảng tiền tố LPS: Time O(M)
  const lps = new Array(m).fill(0);
  let len = 0; // Chiều dài của prefix-suffix trước đó
  let i = 1;

  while (i < m) {
    if (pattern[i] === pattern[len]) {
      len++;
      lps[i] = len;
      i++;
    } else {
      if (len !== 0) {
        len = lps[len - 1]; // Nhảy lùi dựa trên LPS
      } else {
        lps[i] = 0;
        i++;
      }
    }
  }

  // 2. Tìm kiếm trên văn bản Text: Time O(N) (Không bao giờ lùi con trỏ t)
  const occurrences: number[] = [];
  let t = 0; // Pointer text
  let p = 0; // Pointer pattern

  while (t < n) {
    if (text[t] === pattern[p]) {
      t++;
      p++;
    }

    if (p === m) {
      occurrences.push(t - p); // Tìm thấy pattern tại vị trí (t - p)
      p = lps[p - 1];
    } else if (t < n && text[t] !== pattern[p]) {
      if (p !== 0) {
        p = lps[p - 1]; // Nhảy pattern mà KHÔNG lùi t
      } else {
        t++;
      }
    }
  }

  return occurrences;
}

// Triển khai thuật toán Rabin-Karp sử dụng Rolling Hash trong TypeScript
// Time Complexity: Average O(N + M) | Worst O(N * M) | Space O(1)
export function rabinKarp(text: string, pattern: string): number[] {
  const n = text.length;
  const m = pattern.length;
  if (m === 0 || n < m) return [];

  const BASE = 256;
  const MOD = 1000000007;
  const occurrences: number[] = [];

  // Tính h = BASE^(M-1) % MOD
  let h = 1;
  for (let i = 0; i < m - 1; i++) {
    h = (h * BASE) % MOD;
  }

  let patternHash = 0;
  let textHash = 0;

  // Tính hash ban đầu cho pattern và cửa sổ đầu tiên của text: O(M)
  for (let i = 0; i < m; i++) {
    patternHash = (patternHash * BASE + pattern.charCodeAt(i)) % MOD;
    textHash = (textHash * BASE + text.charCodeAt(i)) % MOD;
  }

  // Trượt cửa sổ qua toàn bộ văn bản: O(N)
  for (let i = 0; i <= n - m; i++) {
    // Nếu hash trùng nhau -> Kiểm tra ký tự thực tế chống Spurious Hit
    if (patternHash === textHash) {
      if (text.substring(i, i + m) === pattern) {
        occurrences.push(i);
      }
    }

    // Tính Rolling Hash cho cửa sổ tiếp theo trong O(1)
    if (i < n - m) {
      textHash = (BASE * (textHash - text.charCodeAt(i) * h) + text.charCodeAt(i + m)) % MOD;
      // Đảm bảo mã băm luôn dương trong phép toán modulo
      if (textHash < 0) textHash += MOD;
    }
  }

  return occurrences;
}

// 1. PHƯƠNG PHÁP ĐỆ QUY DFS CƠ BẢN: Time O(N) | Space O(H) (Cho 1 truy vấn)
export class TreeNode {
  val: number;
  left: TreeNode | null = null;
  right: TreeNode | null = null;
  constructor(val: number) { this.val = val; }
}

export function lowestCommonAncestor(
  root: TreeNode | null,
  p: TreeNode,
  q: TreeNode
): TreeNode | null {
  if (!root || root === p || root === q) return root;

  const left = lowestCommonAncestor(root.left, p, q);
  const right = lowestCommonAncestor(root.right, p, q);

  // Nếu p và q nằm ở 2 nhánh con khác nhau -> root chính là LCA!
  if (left && right) return root;

  // Nếu chỉ tìm thấy ở 1 nhánh con -> Trả về nhánh đó
  return left ? left : right;
}

// Thuật toán A* Pathfinding trên ma trận lưới 2D trong TypeScript
// f(n) = g(n) + h(n) | Heuristic: Manhattan Distance
interface Point { x: number; y: number; }

export function aStarPathfinding(
  grid: number[][], // 0: đường đi, 1: vật cản
  start: Point,
  goal: Point
): Point[] | null {
  const rows = grid.length;
  const cols = grid[0].length;

  // Hàm Heuristic Manhattan (Admissible & Consistent cho lưới 4 hướng)
  const heuristic = (p: Point): number => Math.abs(p.x - goal.x) + Math.abs(p.y - goal.y);

  const openSet: Point[] = [start];
  const gScore = new Map<string, number>();
  const fScore = new Map<string, number>();
  const parentMap = new Map<string, Point>();

  const key = (p: Point) => `${p.x},${p.y}`;

  gScore.set(key(start), 0);
  fScore.set(key(start), heuristic(start));

  while (openSet.length > 0) {
    // Bốc node có fScore nhỏ nhất trong openSet
    openSet.sort((a, b) => (fScore.get(key(a)) ?? Infinity) - (fScore.get(key(b)) ?? Infinity));
    const current = openSet.shift()!;

    if (current.x === goal.x && current.y === goal.y) {
      // Đã chạm đích -> Truy vết lại đường đi
      const path: Point[] = [];
      let curr: Point | undefined = current;
      while (curr) {
        path.push(curr);
        curr = parentMap.get(key(curr));
      }
      return path.reverse();
    }

    // Duyệt 4 hướng di chuyển: Lên, Xuống, Trái, Phải
    const directions = [{ x: 0, y: 1 }, { x: 0, y: -1 }, { x: 1, y: 0 }, { x: -1, y: 0 }];
    for (const dir of directions) {
      const neighbor: Point = { x: current.x + dir.x, y: current.y + dir.y };

      // Kiểm tra hợp lệ và không phải vật cản
      if (neighbor.x >= 0 && neighbor.x < rows && neighbor.y >= 0 && neighbor.y < cols && grid[neighbor.x][neighbor.y] === 0) {
        const tentativeG = (gScore.get(key(current)) ?? Infinity) + 1; // Chi phí mỗi bước là 1

        if (tentativeG < (gScore.get(key(neighbor)) ?? Infinity)) {
          parentMap.set(key(neighbor), current);
          gScore.set(key(neighbor), tentativeG);
          fScore.set(key(neighbor), tentativeG + heuristic(neighbor));

          if (!openSet.some(p => p.x === neighbor.x && p.y === neighbor.y)) {
            openSet.push(neighbor);
          }
        }
      }
    }
  }

  return null; // Không tìm thấy đường đi
}

// Thuật toán Tarjan tìm các Thành phần liên thông mạnh (SCC) trong TypeScript
// Time Complexity: O(V + E) | Space Complexity: O(V)
export function tarjanSCC(numVertices: number, adjList: Map<number, number[]>): number[][] {
  let timer = 0;
  const disc = new Array(numVertices).fill(-1);
  const low = new Array(numVertices).fill(-1);
  const onStack = new Array(numVertices).fill(false);
  const stack: number[] = [];
  const sccList: number[][] = [];

  function dfs(u: number) {
    disc[u] = low[u] = ++timer;
    stack.push(u);
    onStack[u] = true;

    const neighbors = adjList.get(u) || [];
    for (const v of neighbors) {
      if (disc[v] === -1) {
        // v chưa được thăm -> Duyệt đệ quy
        dfs(v);
        low[u] = Math.min(low[u], low[v]);
      } else if (onStack[v]) {
        // v đã thăm và đang nằm trên DFS Stack (Cạnh ngược Back-edge)
        low[u] = Math.min(low[u], disc[v]);
      }
    }

    // Nếu u là gốc của một SCC
    if (disc[u] === low[u]) {
      const currentSCC: number[] = [];
      while (true) {
        const node = stack.pop()!;
        onStack[node] = false;
        currentSCC.push(node);
        if (node === u) break;
      }
      sccList.push(currentSCC);
    }
  }

  // Duyệt qua toàn bộ các đỉnh phòng trường hợp đồ thị không liên thông
  for (let i = 0; i < numVertices; i++) {
    if (disc[i] === -1) dfs(i);
  }

  return sccList;
}

// Triển khai thuật toán Edmonds-Karp tìm Luồng Cực Đại (Max Flow) bằng BFS trong TypeScript
// Time Complexity: O(V * E^2) | Space Complexity: O(V^2)
export function edmondsKarpMaxFlow(
  numVertices: number,
  source: number,
  sink: number,
  capacity: number[][] // Ma trận dung lượng capacity[u][v]
): number {
  // Tạo đồ thị phần dư (Residual Capacity)
  const residual: number[][] = capacity.map(row => [...row]);
  let maxFlow = 0;

  // BFS tìm Đường tăng luồng ngắn nhất (ít cạnh nhất) từ Source đến Sink
  const bfsFindPath = (parent: number[]): boolean => {
    const visited = new Array(numVertices).fill(false);
    const queue: number[] = [source];
    visited[source] = true;

    while (queue.length > 0) {
      const u = queue.shift()!;
      if (u === sink) return true; // Đã tìm thấy đường đến Sink

      for (let v = 0; v < numVertices; v++) {
        // Nếu v chưa thăm và dung lượng còn lại trên cạnh u->v lớn hơn 0
        if (!visited[v] && residual[u][v] > 0) {
          visited[v] = true;
          parent[v] = u;
          queue.push(v);
        }
      }
    }
    return false;
  };

  const parent = new Array(numVertices).fill(-1);

  // Lặp trong khi vẫn còn đường tăng luồng trên đồ thị phần dư
  while (bfsFindPath(parent)) {
    // 1. Tìm dung lượng nút thắt cổ chai (Bottleneck Capacity) trên đường vừa tìm được
    let bottleneck = Infinity;
    for (let v = sink; v !== source; v = parent[v]) {
      const u = parent[v];
      bottleneck = Math.min(bottleneck, residual[u][v]);
    }

    // 2. Cập nhật dung lượng cạnh thuận và cạnh nghịch trên đồ thị phần dư
    for (let v = sink; v !== source; v = parent[v]) {
      const u = parent[v];
      residual[u][v] -= bottleneck; // Giảm dung lượng cạnh thuận
      residual[v][u] += bottleneck; // Tăng dung lượng cạnh nghịch (cho phép undo)
    }

    maxFlow += bottleneck;
  }

  return maxFlow;
}
